CREATE TRIGGER search_post_update AFTER UPDATE ON public.activity_posts FOR EACH ROW WHEN (old.title IS DISTINCT FROM new.title OR old.intro IS DISTINCT FROM new.intro OR old.body IS DISTINCT FROM new.body OR old.published_at IS DISTINCT FROM new.published_at OR old.car_id IS DISTINCT FROM new.car_id) EXECUTE FUNCTION public.queue_search_change('update', 'id');
